// Slugs ordered by length DESC for greedy city matching at the end of a slug.
export const SEO_CITIES_BY_SLUG_DESC = [...SEO_CITIES].sort(
  (a, b) => b.slug.length - a.slug.length
)

export function getCityBySlug(slug: string): SeoCity | null {
  return SEO_CITIES.find((c) => c.slug === slug) ?? null
}

export function getCitySlugs(): string[] {
  return SEO_CITIES.map((c) => c.slug)
}
